export default function Navbar({ onNavigate, onLogout, user }) {

  const goToSection = (sectionId) => {
    // Step 1 → switch to home page
    onNavigate("home");

    // Step 2 → wait for Home to render, then scroll
    setTimeout(() => {
      const el = document.getElementById(sectionId);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    }, 50);
  };

  return (
    <nav className="nav">
      <div className="brand" onClick={() => goToSection("home-section")}>
        NGO Portal
      </div>

      <div className="links">
        <button onClick={() => goToSection("home-section")}>Home</button>
        <button onClick={() => goToSection("about-section")}>About Us</button>
        <button onClick={() => goToSection("events-section")}>Events</button>
        <button onClick={() => goToSection("contact-section")}>Contact</button>

        {!user && <button onClick={() => onNavigate("login")}>Login</button>}
        {!user && <button onClick={() => onNavigate("register")}>Register</button>}
        {user && <button onClick={() => onNavigate("dashboard")}>Dashboard</button>}
        {user && <button onClick={onLogout}>Logout</button>}
      </div>
    </nav>
  );
}
